package org.novasos.healthysv2.maternalandchildhealth;
import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;

@Entity @Table(name="prenatal_visit",schema="maternal_child") class PrenatalVisit{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="pregnancy_id",nullable=false)private Pregnancy pregnancy;@Column(name="consultation_id")private UUID consultationId;@Column(name="professional_id")private UUID professionalId;@Column(name="visit_date",nullable=false)private Instant visitDate;@Column(name="gestational_age_weeks")private Integer gestationalAgeWeeks;private BigDecimal weight;@Column(name="systolic_pressure")private Integer systolicPressure;@Column(name="diastolic_pressure")private Integer diastolicPressure;@Column(name="fetal_heart_rate")private Integer fetalHeartRate;@Column(columnDefinition="text")private String notes;protected PrenatalVisit(){}static PrenatalVisit create(Pregnancy p,UUID c,UUID pro,Instant date,Integer weeks,BigDecimal weight,Integer sys,Integer dia,Integer fhr,String notes){var x=new PrenatalVisit();x.id=UUID.randomUUID();x.pregnancy=p;x.consultationId=c;x.professionalId=pro;x.visitDate=date==null?Instant.now():date;x.gestationalAgeWeeks=weeks;x.weight=weight;x.systolicPressure=sys;x.diastolicPressure=dia;x.fetalHeartRate=fhr;x.notes=Values.optional(notes);return x;}UUID getId(){return id;}UUID getConsultationId(){return consultationId;}UUID getProfessionalId(){return professionalId;}Instant getVisitDate(){return visitDate;}Integer getGestationalAgeWeeks(){return gestationalAgeWeeks;}BigDecimal getWeight(){return weight;}Integer getSystolicPressure(){return systolicPressure;}Integer getDiastolicPressure(){return diastolicPressure;}Integer getFetalHeartRate(){return fetalHeartRate;}String getNotes(){return notes;}}
@Entity @Table(name="pregnancy_risk",schema="maternal_child") class PregnancyRisk{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="pregnancy_id",nullable=false)private Pregnancy pregnancy;@Column(name="risk_type",nullable=false,length=150)private String type;@Column(length=30)private String severity;@Column(name="identified_at",nullable=false)private Instant identifiedAt;@Column(columnDefinition="text")private String notes;@Column(nullable=false,length=30)private String status;protected PregnancyRisk(){}static PregnancyRisk create(Pregnancy p,String type,String severity,String notes){var x=new PregnancyRisk();x.id=UUID.randomUUID();x.pregnancy=p;x.type=Values.required(type);x.severity=Values.normalize(severity,"MODERATE");x.identifiedAt=Instant.now();x.notes=Values.optional(notes);x.status="ACTIVE";return x;}void resolve(){if(!"ACTIVE".equals(status))throw new IllegalStateException("Risk already resolved");status="RESOLVED";}UUID getId(){return id;}String getType(){return type;}String getSeverity(){return severity;}Instant getIdentifiedAt(){return identifiedAt;}String getNotes(){return notes;}String getStatus(){return status;}}
@Entity @Table(name="delivery",schema="maternal_child") class Delivery{@Id private UUID id;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="pregnancy_id",nullable=false,unique=true)private Pregnancy pregnancy;@Column(name="organization_id")private UUID organizationId;@Column(name="delivery_date",nullable=false)private Instant deliveryDate;@Column(name="delivery_type",length=50)private String type;@Column(name="professional_id")private UUID professionalId;@Column(columnDefinition="text")private String complications;@Column(columnDefinition="text")private String notes;@OneToMany(mappedBy="delivery",cascade=CascadeType.ALL,orphanRemoval=true)private List<Newborn> newborns=new ArrayList<>();protected Delivery(){}static Delivery create(Pregnancy p,UUID org,Instant date,String type,UUID professional,String complications,String notes,List<Pregnancy.NewbornData> newborns){var x=new Delivery();x.id=UUID.randomUUID();x.pregnancy=p;x.organizationId=org;x.deliveryDate=Objects.requireNonNull(date);x.type=Values.normalize(type,"VAGINAL");x.professionalId=professional;x.complications=Values.optional(complications);x.notes=Values.optional(notes);var orders=new HashSet<Integer>();for(var n:newborns){int order=n.birthOrder()==null?x.newborns.size()+1:n.birthOrder();if(!orders.add(order))throw new IllegalArgumentException("Duplicate birth order");x.newborns.add(Newborn.create(x,n.childPatientId(),order,n.weight(),n.height(),n.headCircumference(),n.apgar1(),n.apgar5()));}return x;}UUID getId(){return id;}UUID getOrganizationId(){return organizationId;}Instant getDeliveryDate(){return deliveryDate;}String getType(){return type;}UUID getProfessionalId(){return professionalId;}String getComplications(){return complications;}String getNotes(){return notes;}List<Newborn> getNewborns(){return newborns;}}
@Entity @Table(name="newborn",schema="maternal_child") class Newborn{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="delivery_id",nullable=false)private Delivery delivery;@Column(name="child_patient_id",nullable=false,unique=true)private UUID childPatientId;@Column(name="birth_order",nullable=false)private Integer birthOrder;@Column(name="birth_weight")private BigDecimal birthWeight;@Column(name="birth_height")private BigDecimal birthHeight;@Column(name="head_circumference")private BigDecimal headCircumference;@Column(name="apgar_1")private Short apgar1;@Column(name="apgar_5")private Short apgar5;@Column(nullable=false,length=30)private String status;protected Newborn(){}static Newborn create(Delivery d,UUID child,int order,BigDecimal weight,BigDecimal height,BigDecimal head,Short a1,Short a5){var x=new Newborn();x.id=UUID.randomUUID();x.delivery=d;x.childPatientId=Objects.requireNonNull(child);x.birthOrder=order;x.birthWeight=weight;x.birthHeight=height;x.headCircumference=head;x.apgar1=a1;x.apgar5=a5;x.status="ACTIVE";return x;}UUID getId(){return id;}UUID getChildPatientId(){return childPatientId;}Integer getBirthOrder(){return birthOrder;}BigDecimal getBirthWeight(){return birthWeight;}BigDecimal getBirthHeight(){return birthHeight;}BigDecimal getHeadCircumference(){return headCircumference;}Short getApgar1(){return apgar1;}Short getApgar5(){return apgar5;}String getStatus(){return status;}}
@Entity @Table(name="postpartum_visit",schema="maternal_child") class PostpartumVisit{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="pregnancy_id",nullable=false)private Pregnancy pregnancy;@Column(name="mother_patient_id",nullable=false)private UUID motherPatientId;@Column(name="professional_id")private UUID professionalId;@Column(name="visit_date",nullable=false)private Instant visitDate;@Column(columnDefinition="text")private String notes;@Column(nullable=false,length=30)private String status;protected PostpartumVisit(){}static PostpartumVisit create(Pregnancy p,UUID mother,UUID professional,Instant date,String notes,String status){var x=new PostpartumVisit();x.id=UUID.randomUUID();x.pregnancy=p;x.motherPatientId=mother;x.professionalId=professional;x.visitDate=date==null?Instant.now():date;x.notes=Values.optional(notes);x.status=Values.normalize(status,"COMPLETED");return x;}UUID getId(){return id;}UUID getProfessionalId(){return professionalId;}Instant getVisitDate(){return visitDate;}String getNotes(){return notes;}String getStatus(){return status;}}

final class Values{private Values(){}static String required(String value){if(value==null||value.isBlank())throw new IllegalArgumentException("Required value");return value.trim();}static String optional(String value){return value==null||value.isBlank()?null:value.trim();}static String normalize(String value,String fallback){return value==null||value.isBlank()?fallback:value.trim().toUpperCase();}}
